import {createTorresTour} from './torres-tour.js';
import {createPhotoTourMedia as createVehicleMedia} from './torres-tour.js';
import {renderVideoLinks} from './vehicle-videos.js';
import {priceView} from './offer-view.js';
import {offerParts} from './offers.js';
import {priceLabel} from './money.js';
import {enhanceStories} from './brand-stories.js';
const el=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n;};
function imageView(vehicle,url){const node=el('div','catalog-photo');if(vehicle.exampleKey&&url==='/assets/reference.png'){node.classList.add('vehicle-image',vehicle.exampleKey);node.setAttribute('role','img');node.setAttribute('aria-label',vehicle.make+' '+vehicle.name);}else{const img=el('img');img.src=url;img.alt=vehicle.make+' '+vehicle.name;img.loading='lazy';node.append(img);}return node;}
function gallery(vehicle,detail=false){const photos=vehicle.photos?.length?vehicle.photos:['/assets/logo.png'],outer=el('div','catalog-gallery'+(detail?' detail-gallery':'')),stage=el('div','catalog-stage'),counter=el('span','photo-counter');let current=0,startX=0;const thumbs=el('div','catalog-thumbs');function draw(i){current=(i+photos.length)%photos.length;stage.querySelector('.catalog-photo')?.remove();stage.prepend(imageView(vehicle,photos[current]));counter.textContent=`${current+1} / ${photos.length}`;[...thumbs.children].forEach((b,index)=>b.setAttribute('aria-pressed',String(index===current)));}
 stage.append(counter);for(const [label,step,glyph]of [['Foto anterior',-1,'‹'],['Foto siguiente',1,'›']]){const b=el('button','photo-arrow '+(step<0?'prev':'next'),glyph);b.type='button';b.setAttribute('aria-label',label+' de '+vehicle.name);b.hidden=photos.length<2;b.onclick=()=>draw(current+step);stage.append(b);}
 if(detail){photos.forEach((url,i)=>{const b=el('button','photo-thumb');b.type='button';b.setAttribute('aria-label','Ver foto '+(i+1));b.append(imageView(vehicle,url));b.onclick=()=>draw(i);thumbs.append(b);});outer.append(stage,thumbs);}else outer.append(stage);
 stage.addEventListener('touchstart',e=>{startX=e.touches[0].clientX;},{passive:true});stage.addEventListener('touchend',e=>{const dx=e.changedTouches[0].clientX-startX;if(Math.abs(dx)>45){outer.dataset.swipingUntil=String(Date.now()+450);draw(current+(dx<0?1:-1));}},{passive:true});draw(0);return outer;}
export function renderCards(vehicles,grid,saved){grid.replaceChildren();for(const v of vehicles){const card=el('article','vehicle-card enhanced-card'),visual=gallery(v),badge=el('span','catalog-badge',v.showcaseDemo?'Demostración · no está en venta':offerParts(v)?'En oferta':v.exampleKey?'Ejemplo editable':'Disponible'),save=el('button','save-button'+(saved.includes(v.id)?' saved':''),saved.includes(v.id)?'♥':'♡');save.type='button';save.dataset.save=v.id;save.setAttribute('aria-label',(saved.includes(v.id)?'Quitar de':'Guardar en')+' favoritos: '+v.name);save.setAttribute('aria-pressed',String(saved.includes(v.id)));visual.append(badge,save);const content=el('div','vehicle-content'),make=el('span','make',v.make),title=el('h3','',v.name),specs=el('div','catalog-specs');for(const val of [v.year,v.mileage,v.transmission,v.fuel].filter(Boolean))specs.append(el('span','',val));const price=priceView(v,el,'catalog-price'),location=el('p','catalog-location',[v.city,v.country].filter(Boolean).join(' · ')||'Consulta la ubicación'),bottom=el('div','card-bottom'),details=el('button','detail-button','Ver fotos y ficha ↗');details.type='button';details.dataset.car=v.id;bottom.append(el('span','',`${v.photos?.length||0} fotos`),details);content.append(make,title,specs,price,location,bottom);card.append(visual,content);card.tabIndex=0;card.setAttribute('aria-label',v.make+' '+v.name+' · Abrir ficha');card.addEventListener('click',event=>{if(event.target.closest('button,a,input,select,textarea'))return;const activeGallery=event.target.closest('.catalog-gallery');if(Number(activeGallery?.dataset.swipingUntil)>Date.now())return;details.click();});card.addEventListener('keydown',event=>{if(event.target===card&&['Enter',' '].includes(event.key)){event.preventDefault();details.click();}});grid.append(card);}}
export function renderDetail(v,container){container.replaceChildren();const layout=el('div','detail-layout'),media=createVehicleMedia(v,gallery(v,true),el),copy=el('div','detail-copy');const title=el('h2','',v.name);title.id='dialog-title';copy.append(el('span','eyebrow',v.make+' · '+(v.showcaseDemo?'DEMOSTRACIÓN · NO ESTÁ EN VENTA':v.exampleKey?'EJEMPLO EDITABLE':'DISPONIBLE')),title,priceView(v,el,'detail-price'),el('p','detail-location',[v.city,v.country].filter(Boolean).join(' · ')));const specs=el('dl','detail-specs');for(const [key,label]of [['year','Año'],['version','Versión'],['engine','Motor'],['transmission','Transmisión'],['drive','Tracción'],['fuel','Combustible'],['mileage','Kilometraje'],['condition','Condición'],['color','Color'],['type','Carrocería']])if(v[key]){const pair=el('div');pair.append(el('dt','',label),el('dd','',v[key]));specs.append(pair);}const text=el('p','detail-description',v.description||'Consulta los detalles de esta unidad con Torres Garage.'),inquire=el('button','button','Consultar este vehículo');inquire.id='inquire';copy.append(specs,el('h3','','Sobre esta unidad'),text);const videos=renderVideoLinks(v,el);if(videos)copy.append(videos);if(v.photoCredits){const credits=el('div','vehicle-3d-note');for(const credit of v.photoCredits){const a=el('a','',credit.label);a.href=credit.url;a.target='_blank';a.rel='noopener noreferrer';credits.append(a,el('br'));}copy.append(credits);}copy.append(inquire);layout.append(media,copy);container.append(layout);}

export const enhanceSections=enhanceStories;
